const results=await Promise.all([
  tools.exec_command({cmd:"rg --files MainProjects/Algebraic-Jacobian-Challenge | rg 'Div(Functor|Family|Degree)|QuotScheme|FGAPicRepresentability'","workdir":"/home/axel/LeanAlgebraicGeometry-Horizon","yield_time_ms":1000,"max_output_tokens":12000}),
  tools.exec_command({cmd:"rg -n \"RepresentableBy|representable|DivFunctor|DivFamily|effective Cartier|flat.*quotient\" MainProjects/Algebraic-Jacobian-Challenge/AlgebraicJacobian/Picard -g '*.lean' | head -n 500","workdir":"/home/axel/LeanAlgebraicGeometry-Horizon","yield_time_ms":1000,"max_output_tokens":35000}),
  tools.exec_command({cmd:"rg -n \"sorry|axiom\" MainProjects/Algebraic-Jacobian-Challenge/AlgebraicJacobian/Picard/DivFunctorDef.lean MainProjects/Algebraic-Jacobian-Challenge/AlgebraicJacobian/Picard/DivFamily.lean MainProjects/Algebraic-Jacobian-Challenge/AlgebraicJacobian/Picard/DivDegree.lean 2>/dev/null","workdir":"/home/axel/LeanAlgebraicGeometry-Horizon","yield_time_ms":1000,"max_output_tokens":12000})
]); for(let i=0;i<results.length;i++) text(`---${i+1}---\n${results[i].output}`);

const results=await Promise.all([
  tools.exec_command({cmd:"sed -n '1,180p' MainProjects/Algebraic-Jacobian-Challenge/AlgebraicJacobian/Picard/QuotRepresentability.lean","workdir":"/home/axel/LeanAlgebraicGeometry-Horizon","yield_time_ms":1000,"max_output_tokens":20000}),
  tools.exec_command({cmd:"rg -n \"sorry|axiom\" MainProjects/Algebraic-Jacobian-Challenge/AlgebraicJacobian/Picard/QuotRepresentability.lean MainProjects/Algebraic-Jacobian-Challenge/AlgebraicJacobian/Picard/QuotFunctorDef.lean MainProjects/Algebraic-Jacobian-Challenge/AlgebraicJacobian/Picard/GrassmannianRepresentability.lean 2>/dev/null","workdir":"/home/axel/LeanAlgebraicGeometry-Horizon","yield_time_ms":1000,"max_output_tokens":12000}),
  tools.exec_command({cmd:"sed -n '720,870p' MainProjects/Algebraic-Jacobian-Challenge/AlgebraicJacobian/Picard/DivFunctorDef.lean","workdir":"/home/axel/LeanAlgebraicGeometry-Horizon","yield_time_ms":1000,"max_output_tokens":22000}),
  tools.exec_command({cmd:"rg -n \"instance.*Flat|flat_quotient|IsLocallyTrivial.*kernel|structure QuotFamily\" MainProjects/Algebraic-Jacobian-Challenge/AlgebraicJacobian/Picard -g '*.lean' | head -n 300","workdir":"/home/axel/LeanAlgebraicGeometry-Horizon","yield_time_ms":1000,"max_output_tokens":24000})
]); for(let i=0;i<results.length;i++) text(`---${i+1}---\n${results[i].output}`);
